import random

def is_girth_at_least_7(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        # BFS to find shortest cycle
        dist = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif dist[v] >= dist[u]:
                    # Cycle found
                    if dist[v] + dist[u] + 1 < 7:
                        return False
    return True

def is_3_colorable(n, edges):
    # Simple backtracking for 3-coloring
    color = [-1] * n
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def solve(u):
        if u == n:
            return True
        for c in range(3):
            if all(color[v] != c for v in adj[u]):
                color[u] = c
                if solve(u + 1):
                    return True
                color[u] = -1
        return False
    return solve(0)

def generate_random_3_regular(n):
    while True:
        nodes = []
        for i in range(n):
            nodes.extend([i, i, i])
        random.shuffle(nodes)
        edges = []
        for i in range(0, len(nodes), 2):
            u, v = nodes[i], nodes[i+1]
            if u != v:
                edges.append(tuple(sorted((u, v))))

        # Check if it's a simple graph (no self-loops, no multiple edges)
        if len(set(edges)) == len(edges) and all(u != v for u, v in edges):
            return edges

